
(async()=>{
  const BARREL_GLB_GZ="";

  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));

  async function waitGame(){
    for(let i=0;i<1000;i++){
      const g=window.gameReview;
      if(
        g?.scene &&
        g?.player &&
        g?.groundY &&
        window.gameZombie &&
        window.FLORESTA_MODULES?.three
      ) return g;
      await sleep(20);
    }
    throw new Error("Jogo não ficou disponível para o Lenhador de Barril.");
  }

  async function gunzipB64(s){
    const bin=atob(s);
    const raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)raw[i]=bin.charCodeAt(i);

    const ds=new DecompressionStream("gzip");
    return await new Response(
      new Blob([raw]).stream().pipeThrough(ds)
    ).arrayBuffer();
  }

  function parseGLB(buffer){
    const dv=new DataView(buffer);

    if(dv.getUint32(0,true)!==0x46546c67){
      throw new Error("GLB inválido.");
    }

    const version=dv.getUint32(4,true);
    if(version!==2)throw new Error("GLB versão não suportada.");

    const total=dv.getUint32(8,true);
    let off=12;
    let json=null;
    let bin=null;

    while(off<total){
      const len=dv.getUint32(off,true);
      const type=dv.getUint32(off+4,true);
      off+=8;

      const chunk=buffer.slice(off,off+len);
      off+=len;

      if(type===0x4e4f534a){
        json=JSON.parse(
          new TextDecoder().decode(new Uint8Array(chunk))
        );
      }else if(type===0x004e4942){
        bin=chunk;
      }
    }

    if(!json||!bin)throw new Error("GLB sem JSON/BIN.");
    return {json,bin};
  }

  function componentCtor(type){
    switch(type){
      case 5120:return Int8Array;
      case 5121:return Uint8Array;
      case 5122:return Int16Array;
      case 5123:return Uint16Array;
      case 5125:return Uint32Array;
      case 5126:return Float32Array;
      default:throw new Error("componentType GLB não suportado: "+type);
    }
  }

  function componentReader(type){
    switch(type){
      case 5120:return (d,o)=>d.getInt8(o);
      case 5121:return (d,o)=>d.getUint8(o);
      case 5122:return (d,o)=>d.getInt16(o,true);
      case 5123:return (d,o)=>d.getUint16(o,true);
      case 5125:return (d,o)=>d.getUint32(o,true);
      case 5126:return (d,o)=>d.getFloat32(o,true);
      default:throw new Error("componentType GLB não suportado: "+type);
    }
  }

  function componentsFor(type){
    return {
      SCALAR:1,
      VEC2:2,
      VEC3:3,
      VEC4:4,
      MAT4:16
    }[type]||1;
  }

  function buildModel(THREE,glbBuffer){
    const {json:gltf,bin}=parseGLB(glbBuffer);
    const accessCache=new Map();

    function accessor(index){
      if(accessCache.has(index))return accessCache.get(index);

      const a=gltf.accessors[index];
      const bv=gltf.bufferViews[a.bufferView];
      const Ctor=componentCtor(a.componentType);
      const comps=componentsFor(a.type);
      const elemBytes=Ctor.BYTES_PER_ELEMENT;
      const stride=bv.byteStride||comps*elemBytes;

      const byteOffset=
        (bv.byteOffset||0)+(a.byteOffset||0);

      let array;

      if(stride===comps*elemBytes && byteOffset%elemBytes===0){
        array=new Ctor(
          bin,
          byteOffset,
          a.count*comps
        );
      }else{
        array=new Ctor(a.count*comps);
        const data=new DataView(bin);
        const read=componentReader(a.componentType);

        for(let i=0;i<a.count;i++){
          const src=byteOffset+i*stride;
          for(let c=0;c<comps;c++){
            array[i*comps+c]=read(src+c*elemBytes);
          }
        }
      }

      const result={
        array,
        itemSize:comps,
        count:a.count,
        componentType:a.componentType,
        normalized:!!a.normalized
      };

      accessCache.set(index,result);
      return result;
    }

    const jointNodes=new Set();
    for(const skin of gltf.skins||[]){
      for(const j of skin.joints||[])jointNodes.add(j);
      if(skin.skeleton!=null)jointNodes.add(skin.skeleton);
    }

    const materials=(gltf.materials||[]).map(m=>{
      const p=m.pbrMetallicRoughness||{};
      const f=p.baseColorFactor||[1,1,1,1];

      return new THREE.MeshStandardMaterial({
        color:new THREE.Color(f[0],f[1],f[2]),
        opacity:f[3]??1,
        transparent:(f[3]??1)<1,
        metalness:p.metallicFactor??0,
        roughness:p.roughnessFactor??1,
        side:m.doubleSided?THREE.DoubleSide:THREE.FrontSide,
        vertexColors:true
      });
    });

    function makeGeometry(meshIndex){
      const primitive=gltf.meshes[meshIndex].primitives[0];
      const geo=new THREE.BufferGeometry();

      const map={
        POSITION:"position",
        NORMAL:"normal",
        COLOR_0:"color",
        JOINTS_0:"skinIndex",
        WEIGHTS_0:"skinWeight"
      };

      for(const [srcName,dstName] of Object.entries(map)){
        const ai=primitive.attributes[srcName];
        if(ai==null)continue;

        const a=accessor(ai);
        geo.setAttribute(
          dstName,
          new THREE.BufferAttribute(
            a.array,
            a.itemSize,
            a.normalized
          )
        );
      }

      geo.computeBoundingSphere();
      return {
        geometry:geo,
        material:materials[primitive.material||0]
      };
    }

    const objects=new Array(gltf.nodes.length);

    // First create every node/object.
    for(let i=0;i<gltf.nodes.length;i++){
      const n=gltf.nodes[i];
      let obj;

      if(n.mesh!=null){
        const built=makeGeometry(n.mesh);
        obj=new THREE.SkinnedMesh(
          built.geometry,
          built.material
        );
        obj.castShadow=true;
        obj.receiveShadow=false;
        obj.frustumCulled=true;
      }else if(jointNodes.has(i)){
        obj=new THREE.Bone();
      }else{
        obj=new THREE.Group();
      }

      obj.name=n.name||("Node_"+i);

      if(n.translation)obj.position.fromArray(n.translation);
      if(n.rotation)obj.quaternion.fromArray(n.rotation);
      if(n.scale)obj.scale.fromArray(n.scale);

      objects[i]=obj;
    }

    // Build hierarchy.
    for(let i=0;i<gltf.nodes.length;i++){
      const n=gltf.nodes[i];
      for(const child of n.children||[]){
        objects[i].add(objects[child]);
      }
    }

    const sceneIndex=gltf.scene??0;
    const sceneDef=gltf.scenes?.[sceneIndex]||{nodes:[0]};
    const root=new THREE.Group();
    root.name="Unique_Barrel_Saw_Lumberjack";

    for(const n of sceneDef.nodes||[]){
      root.add(objects[n]);
    }

    root.updateMatrixWorld(true);

    // Build skeletons from inverse bind matrices.
    const skeletons=(gltf.skins||[]).map(skin=>{
      const bones=(skin.joints||[]).map(i=>objects[i]);
      const inverses=[];

      if(skin.inverseBindMatrices!=null){
        const inv=accessor(skin.inverseBindMatrices).array;

        for(let i=0;i<bones.length;i++){
          const m=new THREE.Matrix4();
          m.fromArray(inv,i*16);
          inverses.push(m);
        }
      }

      return new THREE.Skeleton(
        bones,
        inverses.length?inverses:undefined
      );
    });

    // Bind each skinned mesh.
    for(let i=0;i<gltf.nodes.length;i++){
      const n=gltf.nodes[i];
      if(n.mesh==null||n.skin==null)continue;

      const mesh=objects[i];
      mesh.bind(skeletons[n.skin],mesh.matrixWorld);
      mesh.normalizeSkinWeights();
    }

    function makeClip(anim){
      const tracks=[];

      for(const ch of anim.channels||[]){
        const sampler=anim.samplers[ch.sampler];
        const target=objects[ch.target.node];
        if(!target)continue;

        const times=accessor(sampler.input).array;
        const values=accessor(sampler.output).array;
        const path=ch.target.path;

        if(path==="rotation"){
          tracks.push(
            new THREE.QuaternionKeyframeTrack(
              target.name+".quaternion",
              times,
              values
            )
          );
        }else if(path==="translation"){
          tracks.push(
            new THREE.VectorKeyframeTrack(
              target.name+".position",
              times,
              values
            )
          );
        }else if(path==="scale"){
          tracks.push(
            new THREE.VectorKeyframeTrack(
              target.name+".scale",
              times,
              values
            )
          );
        }
      }

      return new THREE.AnimationClip(
        anim.name||"Animation",
        -1,
        tracks
      );
    }

    const clips=(gltf.animations||[]).map(makeClip);
    root.updateMatrixWorld(true);

    return {root,clips};
  }

  try{
    const game=await waitGame();
    const THREE=await window.__LOCAL_IMPORT(window.FLORESTA_MODULES.three);

    // V43: direct, one-time GLB decode/build using the SAME Three.js instance
    // as the rest of the game. No iframe, no duplicate renderer/document.
    const glbBuffer=await gunzipB64(BARREL_GLB_GZ);
    const built=buildModel(THREE,glbBuffer);

    const root=built.root;
    const clips=built.clips;

    const idleClip=clips.find(c=>c.name==="Idle")||clips[0];
    const walkClip=clips.find(c=>c.name==="Walk")||clips[0];
    const sawClip=clips.find(c=>c.name==="SawSpin")||clips[0];

    if(!idleClip||!walkClip||!sawClip){
      throw new Error("Animações do Lenhador de Barril incompletas.");
    }

    const mixer=new THREE.AnimationMixer(root);

    const idleAction=mixer.clipAction(idleClip);
    const walkAction=mixer.clipAction(walkClip);
    const sawAction=mixer.clipAction(sawClip);

    idleAction.setLoop(THREE.LoopRepeat,Infinity);
    walkAction.setLoop(THREE.LoopRepeat,Infinity);
    sawAction.setLoop(THREE.LoopOnce,1);
    sawAction.clampWhenFinished=true;

    root.scale.setScalar(.86);
    root.visible=false;
    root.name="Unique_Barrel_Saw_Lumberjack";
    game.scene.add(root);

    const cfg={
      hp:260,
      speed:1.08,
      turnSpeed:4.2,
      attackRange:1.72,
      attackCooldown:1250,
      sawDamage:24,
      axeDamage:34,
      axeRange:2.6,
      axeHalfAngleDeg:72,

      spawnMin:18,
      spawnMax:28,
      spawnDelayMin:12000,
      spawnDelayMax:35000,

      bodyRadius:.62,
      logAvoidDistance:1.05
    };

    let hp=cfg.hp;
    let spawnedEver=false;
    let alive=false;
    let state="waiting";
    let currentAction=null;
    let attackDamageDone=false;
    let nextAttackAt=0;
    let lastT=performance.now();
    let updateAccum=0;
    let lastSwing=-1;

    const status=document.getElementById("status");

    function useAction(action,restart=false){
      if(!action)return;
      if(currentAction===action&&!restart)return;

      currentAction?.stop?.();
      action.reset();
      action.enabled=true;
      action.setEffectiveWeight(1);
      action.setEffectiveTimeScale(1);
      action.play();
      currentAction=action;
    }

    function placedLogs(){
      return window.gameLumber?.placedLogs||[];
    }

    const A={x:0,y:0,z:0};
    const B={x:0,y:0,z:0};

    function logSegment(mesh){
      if(!mesh?.parent||mesh.visible===false)return null;

      const len=Math.max(.4,Number(mesh.userData.length)||3);
      const rad=Math.max(.10,Number(mesh.userData.radius)||.22);

      mesh.updateMatrixWorld(true);
      const m=mesh.matrixWorld.elements;

      const hx=m[4]*(len*.5);
      const hy=m[5]*(len*.5);
      const hz=m[6]*(len*.5);

      A.x=m[12]-hx; A.y=m[13]-hy; A.z=m[14]-hz;
      B.x=m[12]+hx; B.y=m[13]+hy; B.z=m[14]+hz;

      return {ax:A.x,az:A.z,bx:B.x,bz:B.z,rad};
    }

    function closestXZ(px,pz,seg){
      const abx=seg.bx-seg.ax;
      const abz=seg.bz-seg.az;
      const ab2=abx*abx+abz*abz;

      let t=0;
      if(ab2>.000001){
        t=clamp(
          ((px-seg.ax)*abx+(pz-seg.az)*abz)/ab2,
          0,1
        );
      }

      const qx=seg.ax+abx*t;
      const qz=seg.az+abz*t;
      const dx=px-qx;
      const dz=pz-qz;

      return {
        qx,qz,dx,dz,
        dist:Math.hypot(dx,dz)
      };
    }

    function resolveLogCollision(){
      for(const mesh of placedLogs()){
        const seg=logSegment(mesh);
        if(!seg)continue;

        const c=closestXZ(
          root.position.x,
          root.position.z,
          seg
        );

        const minDist=cfg.bodyRadius+seg.rad;
        if(c.dist>=minDist)continue;

        let nx=c.dx,nz=c.dz,d=c.dist;

        if(d<.001){
          nx=-(seg.bz-seg.az);
          nz=(seg.bx-seg.ax);
          d=Math.hypot(nx,nz)||1;
        }

        nx/=d;
        nz/=d;

        const push=minDist-c.dist+.02;
        root.position.x+=nx*push;
        root.position.z+=nz*push;
      }
    }

    function steerAroundLogs(dx,dz){
      let sx=dx,sz=dz;

      const len=Math.hypot(dx,dz)||1;
      const nx=dx/len,nz=dz/len;

      const lookX=
        root.position.x+nx*cfg.logAvoidDistance;
      const lookZ=
        root.position.z+nz*cfg.logAvoidDistance;

      for(const mesh of placedLogs()){
        const seg=logSegment(mesh);
        if(!seg)continue;

        const c=closestXZ(lookX,lookZ,seg);
        const trigger=cfg.bodyRadius+seg.rad+.45;
        if(c.dist>=trigger)continue;

        const tx=seg.bx-seg.ax;
        const tz=seg.bz-seg.az;
        const tl=Math.hypot(tx,tz)||1;

        let ax=tx/tl,az=tz/tl;
        if(ax*nx+az*nz<0){
          ax=-ax;
          az=-az;
        }

        sx+=ax*1.6;
        sz+=az*1.6;

        if(c.dist>.001){
          sx+=(c.dx/c.dist)*.7;
          sz+=(c.dz/c.dist)*.7;
        }
      }

      const sl=Math.hypot(sx,sz)||1;
      return {x:sx/sl,z:sz/sl};
    }

    function blockedByLog(){
      const ax=root.position.x,az=root.position.z;
      const bx=game.player.x,bz=game.player.z;

      const vx=bx-ax,vz=bz-az;
      const vv=vx*vx+vz*vz;
      if(vv<.0001)return false;

      for(const mesh of placedLogs()){
        const seg=logSegment(mesh);
        if(!seg)continue;

        const mx=(seg.ax+seg.bx)*.5;
        const mz=(seg.az+seg.bz)*.5;
        const t=((mx-ax)*vx+(mz-az)*vz)/vv;

        if(t<=0||t>=1)continue;

        const px=ax+vx*t;
        const pz=az+vz*t;
        const c=closestXZ(px,pz,seg);

        if(c.dist<seg.rad+.32)return true;
      }

      return false;
    }

    function randomSpawnPoint(testMode=false){
      if(testMode){
        const yaw=game.player.yaw||0;
        return {
          x:game.player.x-Math.sin(yaw)*6,
          z:game.player.z-Math.cos(yaw)*6
        };
      }

      const angle=Math.random()*Math.PI*2;
      const radius=
        cfg.spawnMin+
        Math.random()*(cfg.spawnMax-cfg.spawnMin);

      return {
        x:game.player.x+Math.sin(angle)*radius,
        z:game.player.z+Math.cos(angle)*radius
      };
    }

    function spawn(){
      // V56: one alive at a time, but manual respawn after death is allowed.
      if(alive)return false;

      spawnedEver=true;
      alive=true;
      hp=cfg.hp;
      state="walk";
      attackDamageDone=false;
      nextAttackAt=
        performance.now()+900+Math.random()*700;

      const testMode=
        new URLSearchParams(location.search)
          .get("barreltest")==="1";

      const p=randomSpawnPoint(testMode);

      root.position.set(
        p.x,
        game.groundY(p.x,p.z),
        p.z
      );

      root.rotation.set(
        0,
        Math.random()*Math.PI*2,
        0
      );

      root.visible=true;
      useAction(walkAction,true);

      if(status){
        status.textContent=
          "Um Lenhador de Barril apareceu em algum lugar da floresta";
      }

      return true;
    }

    function die(){
      if(!alive)return;

      const deathPosition=root.position.clone();

      alive=false;
      state="dead";
      hp=0;
      mixer.stopAllAction();

      window.gameProgression?.dropXP?.(
        180,
        deathPosition,
        "Lenhador de Barril"
      );

      setTimeout(()=>{
        root.visible=false;
      },450);

      if(status){
        status.textContent=
          "Lenhador de Barril derrotado";
      }
    }

    function updateAI(dt,now){
      if(!alive||!root.visible)return;

      const dx=game.player.x-root.position.x;
      const dz=game.player.z-root.position.z;
      const dist=Math.hypot(dx,dz);

      const desiredYaw=Math.atan2(dx,dz);
      const diff=wrap(desiredYaw-root.rotation.y);

      root.rotation.y+=
        diff*(1-Math.exp(-cfg.turnSpeed*dt));

      if(state==="attack"){
        const t=
          sawAction.time/
          Math.max(.001,sawClip.duration);

        if(!attackDamageDone&&t>=.48){
          attackDamageDone=true;

          const nowDist=Math.hypot(
            game.player.x-root.position.x,
            game.player.z-root.position.z
          );

          if(
            nowDist<=cfg.attackRange+.25 &&
            !blockedByLog()
          ){
            window.gameZombie?.hurtPlayer?.(
              cfg.sawDamage,
              "Lenhador de Barril",
              "barrel-saw"
            );
          }
        }

        if(
          !sawAction.isRunning?.() ||
          sawAction.time>=sawClip.duration-.02
        ){
          state="walk";
          useAction(walkAction,true);
        }

        return;
      }

      if(
        dist<=cfg.attackRange &&
        now>=nextAttackAt &&
        !blockedByLog()
      ){
        state="attack";
        attackDamageDone=false;
        nextAttackAt=
          now+
          cfg.attackCooldown+
          Math.random()*450;

        useAction(sawAction,true);
        return;
      }

      state="walk";
      useAction(walkAction);

      if(dist>.85){
        const dir=steerAroundLogs(dx,dz);

        const step=Math.min(
          cfg.speed*dt,
          Math.max(0,dist-.82)
        );

        root.position.x+=dir.x*step;
        root.position.z+=dir.z*step;

        resolveLogCollision();

        root.position.y=
          game.groundY(
            root.position.x,
            root.position.z
          );
      }
    }

    function axeFacingOk(){
      const dx=root.position.x-game.player.x;
      const dz=root.position.z-game.player.z;
      const d=Math.hypot(dx,dz);

      if(d<.001)return true;

      const tx=dx/d,tz=dz/d;
      const fx=-Math.sin(game.player.yaw);
      const fz=-Math.cos(game.player.yaw);

      return (
        fx*tx+fz*tz
      )>=Math.cos(
        cfg.axeHalfAngleDeg*Math.PI/180
      );
    }

    function onAxeImpact(e){
      if(!alive)return;
      if(window.gameRightHand?.current!=="axe")return;

      const swing=
        e.detail?.swingId??
        performance.now();

      if(swing===lastSwing)return;

      const d=Math.hypot(
        root.position.x-game.player.x,
        root.position.z-game.player.z
      );

      if(
        d>cfg.axeRange ||
        !axeFacingOk()
      )return;

      lastSwing=swing;
      const axeDamage=
        window.gameProgression?.modifyAxeDamage?.(cfg.axeDamage)
        ?? cfg.axeDamage;

      hp=Math.max(0,hp-axeDamage);

      if(status){
        status.textContent=
          `Machado acertou Lenhador de Barril • ${hp}/${cfg.hp} HP`;
      }

      if(hp<=0)die();
    }

    window.addEventListener(
      "game:axe-impact",
      onAxeImpact
    );

    mixer.addEventListener("finished",e=>{
      if(!alive)return;

      if(
        e.action===sawAction &&
        state==="attack"
      ){
        state="walk";
        useAction(walkAction,true);
      }
    });

    function loop(now){
      requestAnimationFrame(loop);if(window.gameSpiderCave?.active)return;

      const dt=Math.min(
        .05,
        Math.max(0,(now-lastT)/1000)
      );

      lastT=now;

      if(!root.visible)return;

      updateAccum+=dt;
      if(updateAccum<(1/30))return;

      const step=Math.min(.066,updateAccum);
      updateAccum=0;

      mixer.update(step);
      updateAI(step,now);
    }

    requestAnimationFrame(loop);if(window.gameSpiderCave?.active)return;

    const testMode=
      new URLSearchParams(location.search)
        .get("barreltest")==="1";

    const delay=testMode
      ? 900
      : cfg.spawnDelayMin+
        Math.random()*
        (cfg.spawnDelayMax-cfg.spawnDelayMin);

    // Disabled automatically: the first nights are controlled by V56.
    if(testMode)setTimeout(spawn,delay);

    window.gameBarrelLumberjack={
      get alive(){return alive;},
      get spawnedEver(){return spawnedEver;},
      get hp(){return hp;},
      get maxHp(){return cfg.hp;},
      get state(){return state;},
      get model(){return root;},
      get spawnDelay(){return delay;},
      get loaderType(){return "direct-glb-main-three";},
      get animations(){
        return {
          idle:"Idle",
          walk:"Walk",
          attack:"SawSpin"
        };
      },
      spawnNow(){return spawn();}
    };

    if(status&&!testMode){
      status.textContent=
        "Lenhador de Barril disponível no Diretor de Spawn";
    }

  }catch(err){
    console.error(
      "Lenhador de Barril:",
      err
    );

    const status=document.getElementById("status");
    if(status){
      status.textContent+=
        " • Lenhador de Barril indisponível: "+
        String(err?.message||err);
    }
  }
})();
